filter.template:
{#- Abendessen der nächsten sieben Tage; ein Tipp auf ein geplantes Gericht bietet an, es auf einen anderen Abend zu legen oder wieder vom Plan zu nehmen -#}
{%- set wt = ['Montag', 'Dienstag', 'Mittwoch', 'Donnerstag', 'Freitag', 'Samstag', 'Sonntag'] -%}
{%- set stil = {
  'card': [{'padding': '9px 14px'}, {'border-radius': '0'}, {'border': 'none'}, {'border-bottom': '1px solid var(--divider-color)'}, {'box-shadow': 'none'}, {'background': 'none'}],
  'grid': [{'grid-template-areas': '"n l"'}, {'grid-template-columns': '96px 1fr'}, {'column-gap': '10px'}, {'align-items': 'center'}],
  'name': [{'justify-self': 'start'}, {'font-size': '14px'}, {'font-weight': '600'}],
  'label': [{'justify-self': 'start'}, {'text-align': 'left'}, {'font-size': '14px'}, {'white-space': 'normal'}]} -%}
{%- set rows = namespace(l=[]) -%}
{#- Portionenzahl je Planeintrag (nur gemerkt, wenn über die Karte eingeplant) -#}
{%- set std = states('input_number.einkauf_portionen') | float(0) -%}
{%- set pm = namespace(d={}) -%}
{%- set alt = states('input_text.einkauf_portionen_plan') -%}
{%- for x in (alt.split(';') if alt not in ['unknown', 'unavailable', ''] else []) if '=' in x -%}{%- set pm.d = dict(pm.d, **{x.split('=')[0]: x.split('=')[1] | float(0)}) -%}{%- endfor -%}
{#- Die sieben Tage mit dem, was dort schon steht: Ziele zum Verschieben -#}
{%- set tage = namespace(l=[]) -%}
{%- for p in state_attr('sensor.wochenkorb_rezepte_DEINE_PLZ', 'plan') or [] -%}
{%- set d = strptime(p.date, '%Y-%m-%d') -%}
{%- set diff = (d.date() - now().date()).days -%}
{%- if diff >= 0 and diff < 7 -%}
{%- set tage.l = tage.l + [{'d': p.date, 'text': 'Heute' if diff == 0 else ('Morgen' if diff == 1 else wt[d.weekday()][:2] ~ ', ' ~ d.strftime('%d.%m.')), 'essen': p.dinner | map(attribute='name') | join(', ')}] -%}
{%- endif -%}
{%- endfor -%}
{%- for p in state_attr('sensor.wochenkorb_rezepte_DEINE_PLZ', 'plan') or [] -%}
{%- set d = strptime(p.date, '%Y-%m-%d') -%}
{%- set diff = (d.date() - now().date()).days -%}
{%- if diff >= 0 and diff < 7 -%}
{%- set tag = 'Heute' if diff == 0 else ('Morgen' if diff == 1 else wt[d.weekday()][:2] ~ ', ' ~ d.strftime('%d.%m.')) -%}
{%- if p.dinner | count == 0 -%}
{%- set rows.l = rows.l + [{'type': 'custom:button-card', 'name': tag, 'label': 'noch frei', 'show_icon': 0, 'show_label': 1, 'tap_action': {'action': 'none'},
  'styles': dict(stil, label=stil.label + [{'color': 'var(--secondary-text-color)'}], card=stil.card + [{'cursor': 'default'}])}] -%}
{%- endif -%}
{%- for e in p.dinner -%}
{%- set weg = {'type': 'custom:button-card', 'name': 'Vom Plan nehmen', 'icon': 'mdi:calendar-remove', 'layout': 'icon_name',
  'tap_action': {'action': 'fire-dom-event', 'browser_mod': {'service': 'browser_mod.sequence', 'data': {'sequence': [
    {'service': 'browser_mod.close_popup', 'data': {}},
    {'service': 'browser_mod.notification', 'data': {'message': '„' ~ e.name ~ '“ wird vom Plan genommen, die Zutaten gehen von der Einkaufsliste', 'duration': 6000}},
    {'service': 'script.einkauf_rezept_ausplanen', 'data': {'slug': e.slug, 'datum': p.date}}]}}},
  'styles': {'card': [{'padding': '10px 14px'}, {'border-radius': '12px'}, {'border': 'none'}, {'box-shadow': 'none'}, {'background': 'rgba(214,69,61,0.9)'}, {'color': '#fff'}],
             'icon': [{'width': '20px'}, {'color': '#fff'}], 'grid': [{'grid-template-columns': 'min-content min-content'}, {'justify-content': 'center'}, {'column-gap': '6px'}]}} -%}
{%- set port = pm.d.get(e.id | string, 0) -%}
{%- set ptext = (port | round(1) | string | replace('.0', '') | replace('.', ',')) ~ ' Port.' -%}
{%- set mengen = namespace(l=[]) -%}
{%- for o in [2, 3, 4, 6, 8] if o != port -%}
{%- set mengen.l = mengen.l + [{'type': 'custom:button-card', 'name': o ~ ' Port.', 'show_icon': 0,
  'tap_action': {'action': 'fire-dom-event', 'browser_mod': {'service': 'browser_mod.sequence', 'data': {'sequence': [
    {'service': 'browser_mod.close_popup', 'data': {}},
    {'service': 'browser_mod.notification', 'data': {'message': '„' ~ e.name ~ '“ wird auf ' ~ o ~ ' Portionen umgerechnet, die Einkaufsliste wird angepasst', 'duration': 6000}},
    {'service': 'script.einkauf_rezept_portionen', 'data': {'slug': e.slug, 'datum': p.date, 'portionen': o}}]}}},
  'styles': {'card': [{'padding': '8px 4px'}, {'border-radius': '12px'}, {'border': 'none'}, {'box-shadow': 'none'}, {'background': 'rgba(127,127,127,0.18)'}],
             'name': [{'font-size': '13px'}, {'font-weight': '600'}]}}] -%}
{%- endfor -%}
{%- set ziele = namespace(l=[]) -%}
{%- for t in tage.l if t.d != p.date -%}
{%- set ziele.l = ziele.l + [{'type': 'custom:button-card', 'name': t.text, 'label': t.essen or 'frei', 'show_icon': 0, 'show_label': 1,
  'tap_action': {'action': 'fire-dom-event', 'browser_mod': {'service': 'browser_mod.sequence', 'data': {'sequence': [
    {'service': 'browser_mod.close_popup', 'data': {}},
    {'service': 'browser_mod.notification', 'data': {'message': '„' ~ e.name ~ '“ wird auf ' ~ t.text ~ ' verschoben', 'duration': 4000}},
    {'service': 'script.einkauf_rezept_verschieben', 'data': {'slug': e.slug, 'von': p.date, 'nach': t.d}}]}}},
  'styles': {
    'card': [{'padding': '10px 14px'}, {'border-radius': '12px'}, {'border': 'none'}, {'box-shadow': 'none'}, {'background': 'rgba(127,127,127,0.18)'}],
    'grid': [{'grid-template-areas': '"n l"'}, {'grid-template-columns': 'auto 1fr'}, {'column-gap': '12px'}],
    'name': [{'justify-self': 'start'}, {'font-size': '15px'}, {'font-weight': '600'}],
    'label': [{'justify-self': 'end'}, {'font-size': '13px'}, {'opacity': '0.8'}, {'text-align': 'right'}]}}] -%}
{%- endfor -%}
{%- set tipp = {'action': 'fire-dom-event', 'browser_mod': {'service': 'browser_mod.popup', 'data': {'title': e.name, 'content': {'type': 'vertical-stack', 'cards':
    [{'type': 'markdown', 'content': 'Geplant für **' ~ tag ~ '**. Auf einen anderen Abend legen:'}] + ziele.l +
    [{'type': 'markdown', 'content': ('Eingekauft wird für **' ~ ptext ~ '** Ändern auf:') if port > 0 else 'Portionen ändern auf:'}, {'type': 'horizontal-stack', 'cards': mengen.l},
     {'type': 'markdown', 'content': 'Beim Entfernen werden auch die Zutaten dieses Rezepts wieder von der Einkaufsliste genommen.'}, weg]}}}} if e.slug else {'action': 'none'} -%}
{%- set rows.l = rows.l + [{'type': 'custom:button-card', 'name': tag if loop.first else '', 'label': e.name ~ ((' · ' ~ ptext) if port > 0 and port != std else ''), 'show_icon': 0, 'show_label': 1, 'tap_action': tipp, 'styles': stil}] -%}
{%- endfor -%}
{%- endif -%}
{%- endfor -%}
{{ rows.l | tojson }}

