{#- Portionenzahl, mit der dieser Eintrag eingeplant wurde -#}
{%- set ns = namespace(p=0) -%}
{%- set alt = states('input_text.einkauf_portionen_plan') -%}
{%- for x in (alt.split(';') if alt not in ['unknown', 'unavailable', ''] else []) if x.split('=')[0] == (eintrag | string) -%}{%- set ns.p = x.split('=')[1] | float(0) -%}{%- endfor -%}
