{%- set ns = namespace(l=[]) -%}
{%- for x in (alt.split(';') if alt not in ['unknown', 'unavailable', ''] else []) if '=' in x and x.split('=')[0] != (eintrag | string) -%}{%- set ns.l = ns.l + [x] -%}{%- endfor -%}
{{ ns.l | join(';') }}

variables.plan:
{%- set heute = now() -%}
{%- set woche = (heute.date() - strptime(start, '%Y-%m-%d').date()).days // 7 -%}
{%- set saison = obst_saison[heute.month - 1] -%}
{#- Vorrat-Merker: "Name=Datum;Name=Datum", bis zu diesem Datum wird der Artikel nicht erneut eingetragen -#}
{%- set vt = states('input_text.einkauf_vorrat') -%}
{%- set vorrat = namespace(m={}) -%}
{%- for p in (vt.split(';') if vt not in ['unknown', 'unavailable', ''] else []) if '=' in p -%}
{%- if p.split('=')[1] >= heute.date().isoformat() -%}{%- set vorrat.m = dict(vorrat.m, **{p.split('=')[0]: p.split('=')[1]}) -%}{%- endif -%}
{%- endfor -%}
{#- Vom wöchentlichen Kassenbon-Abgleich gepflegte Werte: übliche Grundpreise und Rhythmus je Artikel -#}
{%- set werte = namespace(p={}, r={}) -%}
{%- set pt = states('input_text.einkauf_preise') -%}
{%- for p in (pt.split(';') if pt not in ['unknown', 'unavailable', ''] else []) if '=' in p -%}{%- set werte.p = dict(werte.p, **{p.split('=')[0]: p.split('=')[1] | float(0)}) -%}{%- endfor -%}
{%- set rt = states('input_text.einkauf_rhythmus') -%}
{%- for p in (rt.split(';') if rt not in ['unknown', 'unavailable', ''] else []) if '=' in p -%}{%- set werte.r = dict(werte.r, **{p.split('=')[0]: p.split('=')[1] | int(0)}) -%}{%- endfor -%}
{#- Alle aktuellen Angebote von Marktkauf, REWE und EDEKA, die Freitag/Samstag gelten -#}
{%- set ang = namespace(l=[]) -%}
{%- for s in states.sensor | selectattr('entity_id', 'match', 'sensor\\.wochenkorb_') | selectattr('attributes.retailer_name', 'defined') | rejectattr('attributes.retailer_name', 'none') -%}
{%- set a = s.attributes -%}
{%- set h = a.retailer_name | lower -%}
{%- set markt = 'Marktkauf' if h.startswith('marktkauf') else ('REWE' if h.startswith('rewe') else ('EDEKA' if h.startswith('edeka') else '')) -%}
{%- set von = (a.valid_from | as_datetime) if a.valid_from else none -%}
{%- set ende = (a.valid_to | as_datetime) if a.valid_to else none -%}
{%- if markt and (von is none or von <= heute + timedelta(days=1)) and (ende is none or ende >= heute + timedelta(hours=18)) -%}
{%- set preis = s.state | float(0) -%}
{%- set alt = a.old_price | float(0) -%}
{%- set ang.l = ang.l + [{'begriff': s.entity_id | regex_replace('^sensor\\.wochenkorb_(.*)_\\d+_\\d+$', '\\1'), 'liste': a.liste | default(''), 'ohne': a.liste_ohne | default(''), 'sorte': a.suchbegriff | default(''), 'markt': markt, 'schluessel': ((markt ~ '|' ~ ((a.product_name or '') | lower) ~ '|' ~ ('%.2f' | format(s.state | float(0)))) | md5)[:6], 'produkt': a.product_name or '', 'text': ((a.brand_name or '') ~ ' ' ~ (a.product_name or '')) | lower, 'preis': preis, 'wert': ((a.grundpreis | float(0)) if a.grundpreis and a.grundpreis_einheit in ['kg', 'l'] else preis), 'gp': (a.grundpreis | float(0)) if a.grundpreis and a.grundpreis_einheit in ['kg', 'l'] else 0, 'gpe': a.grundpreis_einheit or '', 'rabatt': ((1 - preis / alt) * 100) | round | int if alt > preis else 0}] -%}
{%- endif -%}
{%- endfor -%}
{%- set euro = '%.2f' -%}
{%- set out = namespace(l=[]) -%}
{%- for art in artikel -%}
{%- set alle = (werte.r[art.name] if art.name in werte.r and werte.r[art.name] >= 1 else art.alle) -%}
{%- set normal = (werte.p[art.name] if art.name in werte.p and werte.p[art.name] > 0 else (art.normal | default(0))) -%}
{%- set faellig = woche % alle == art.versatz % alle -%}
{%- set gesperrt = art.name in vorrat.m -%}
{%- set best = namespace(gp=0, o=none) -%}
{%- for o in ang.l if art.begriffe is defined and o.begriff in art.begriffe and (art.regel is not defined or o.text is search(art.regel)) -%}
{%- set gp = o.gp if o.gp > 0 else ((o.preis / art.pack) if art.pack is defined else 0) -%}
{%- if gp > 0 and (best.o is none or gp < best.gp) -%}{%- set best.gp = gp -%}{%- set best.o = o -%}{%- endif -%}
{%- endfor -%}
{%- set ersparnis = (1 - best.gp / normal) if best.o is not none and normal > 0 else 0 -%}
{%- set lohnt = ersparnis >= 0.15 -%}
{%- set faktor = [(4 if ersparnis >= 0.30 else 2), art.max_faktor | default(1)] | min if lohnt else 1 -%}
{%- set normal_text = (art.anzahl ~ ' ' ~ art.einheit) if art.anzahl is defined else (art.menge | default('')) -%}
{%- if art.obst is defined -%}
{%- if faellig -%}
{#- Höchstens 5 Obstsorten: je Sorte das beste Angebot, rabattierte zuerst, dann nach Grundpreis -#}
{%- set tipps = namespace(l=[], sorten=[], schluessel=[]) -%}
{#- Die Sorten kommen aus der freien Liste der Integration (Standard: Liste "Obst", sonst art.liste) -#}
{%- set obst = ang.l | selectattr('liste', 'eq', art.liste | default('Obst')) | list -%}
{%- for o in (obst | selectattr('rabatt', 'gt', 0) | sort(attribute='rabatt', reverse=true) | list) + (obst | selectattr('rabatt', 'eq', 0) | sort(attribute='wert') | list) -%}
{%- if o.begriff not in tipps.sorten and tipps.l | count < 5 and not (o.ohne and o.text is search(o.ohne)) -%}
{%- set tipps.sorten = tipps.sorten + [o.begriff] -%}
{%- set tipps.schluessel = tipps.schluessel + [o.schluessel] -%}
{%- set tipps.l = tipps.l + [(o.sorte or o.begriff) ~ ' ' ~ (euro | format(o.preis) | replace('.', ',')) ~ ' € (' ~ (('−' ~ o.rabatt ~ ' %, ') if o.rabatt > 0 else '') ~ o.markt ~ ')'] -%}
{%- endif -%}
