{%- set menge = ((art.anzahl * faktor) ~ ' ' ~ art.einheit) if art.anzahl is defined else normal_text -%}
{%- set reichweite = faktor * alle -%}
{%- set out.l = out.l + [{'name': art.name, 'text': ([menge, hinweis, ('Vorrat für ' ~ reichweite ~ ' Wochen') if faktor > 1 else ''] | select | join(' · ')), 'angebot': 1, 'vorrat': (heute.date() + timedelta(days=reichweite * 7 - 1)).isoformat() if faktor > 1 else '', 'schluessel': [o.schluessel]}] -%}
{%- elif faellig and not gesperrt -%}
