{%- set rows.l = [{'type': 'section', 'label': 'Keine Angebote für „' ~ q ~ '“ bei Marktkauf, REWE und EDEKA'}] -%}
{%- else -%}
{%- set ns = namespace(seen=[], zeilen=[]) -%}
{%- for a in treffer -%}
{%- set h = (a.retailer or '') | lower -%}
{%- set markt = 'Marktkauf' if h.startswith('marktkauf') else ('REWE' if h.startswith('rewe') else ('EDEKA' if h.startswith('edeka') else (a.retailer or ''))) -%}
{%- set produkt = a.name or '' -%}
{%- set einheit = ((a.description or '') | regex_findall('je (.+?)(?= zzgl| oder |, |$)') | first | default('')) | trim | regex_replace('\\.$', '') -%}
{%- set preis = a.price | float(0) -%}
{%- set key = markt ~ (produkt | lower) ~ preis ~ einheit -%}
{%- if key not in ns.seen -%}
{%- set ns.seen = ns.seen + [key] -%}
{%- set marke = a.brand if a.brand and 'nobrand' not in a.brand and not (produkt | lower).startswith(a.brand | lower) else '' -%}
{%- set alt = a.old_price | float(0) -%}
{%- set gp = ('%.2f' | format(a.grundpreis | float(0)) | replace('.', ',') ~ ' €/' ~ a.grundpreis_einheit) if a.grundpreis and a.grundpreis_einheit else '' -%}
{%- set von = (a.valid_from | as_datetime) if a.valid_from else none -%}
{%- set ende = (a.valid_to | as_datetime) if a.valid_to else none -%}
{%- set ab = (von | as_local).strftime('%d.%m.') if von is not none and von > now() else '' -%}
{%- set bis = (ende | as_local).strftime('%d.%m.') if ende is not none else '' -%}
{%- set zeit = ((('ab ' ~ ab ~ ' ') if ab else '') ~ 'bis ' ~ bis) if bis else '' -%}
{%- set pt = '%.2f' | format(preis) | replace('.', ',') -%}
{%- set ns.zeilen = ns.zeilen + [{'bild': a.image or '', 'link': a.link or '', 'name': ((marke ~ ' ') if marke else '') ~ (produkt | title), 'infos': [markt, einheit, gp, zeit] | select | join(' · '), 'preis': pt, 'alt': ('%.2f' | format(alt) | replace('.', ',')) if alt > preis else '', 'rabatt': ((1 - preis / alt) * 100) | round | int if alt > preis else 0, 'notiz': [markt ~ ' ' ~ pt ~ ' €', einheit, zeit] | select | join(' · ')}] -%}
{%- endif -%}
{%- endfor -%}
{%- set rows.l = [{'type': 'section', 'label': ns.zeilen | count ~ ' Treffer für „' ~ q ~ '“'}] -%}
{%- for z in ns.zeilen | sort(attribute='rabatt', reverse=true) -%}
{%- set rows.l = rows.l + [{'type': 'custom:button-card', 'template': 'angebot_zeile', 'entity': 'sensor.wochenkorb_suche_DEINE_PLZ_GERAET_X', 'variables': {'bild': z.bild, 'link': z.link, 'name': z.name | e, 'infos': z.infos | e, 'preis': z.preis, 'alt': z.alt, 'rabatt': z.rabatt | string, 'eintrag': z.name, 'notiz': z.notiz}}] -%}
{%- endfor -%}
{%- endif -%}
{{ rows.l | tojson }}

