  'tap_action': {'action': 'call-service', 'service': 'input_number.set_value', 'service_data': {'entity_id': 'input_number.rezept_portionen_wahl', 'value': o}},
  'state': [{'operator': '==', 'value': o, 'styles': {'card': [{'background': 'var(--primary-color)'}, {'color': 'var(--text-primary-color, #fff)'}]}}],
  'styles': {'card': [{'padding': '8px 6px'}, {'border-radius': '12px'}, {'border': 'none'}, {'box-shadow': 'none'}, {'background': 'rgba(127,127,127,0.18)'}],
             'name': [{'font-size': '14px'}, {'font-weight': '600'}]}}] -%}
{%- endfor -%}
{%- for r in res[:5] -%}
{%- set o = r.offer -%}
{%- set h = (o.retailer or '') | lower -%}
{%- set markt = 'Marktkauf' if h.startswith('marktkauf') else ('REWE' if h.startswith('rewe') else ('EDEKA' if h.startswith('edeka') else (o.retailer or ''))) -%}
{%- set preis = '%.2f' | format(o.price | float(0)) | replace('.', ',') -%}
{%- set info = r.ingredient ~ ' · ' ~ markt ~ ' ' ~ preis ~ ' €' -%}
{%- set mehr = ('auch im Angebot: ' ~ (r.also_on_offer[:3] | join(', '))) if r.also_on_offer else '' -%}
{#- Eingeplante Rezepte bleiben stehen; Hauptzutaten, die schon auf der Einkaufsliste stehen, werden genannt -#}
{%- set tag = strptime(r.planned, '%Y-%m-%d') if r.planned else none -%}
{%- set geplant = ('eingeplant für ' ~ wt[tag.weekday()] ~ ', ' ~ tag.strftime('%d.%m.')) if tag else '' -%}
{#- Keine true/false in den Zeilen: Home Assistant liefert die Liste sonst als Text und auto-entities zeigt nichts -#}
{#- Kalender-Knopf: Fenster mit den Abenden; die Auswahl läuft auf dem Gerät selbst und braucht keine browser_mod-Registrierung -#}
{%- set knoepfe = namespace(l=[{'type': 'markdown', 'content': '**' ~ r.name ~ '**

Tippe auf den Abend. Der Vorschlag ist der nächste freie.'}, {'type': 'horizontal-stack', 'cards': pk.l}]) -%}
