    {'service': 'browser_mod.notification', 'data': {'message': '„' ~ r.name ~ '“ wird für ' ~ t.text ~ ' eingeplant, die Zutaten kommen auf die Einkaufsliste', 'duration': 6000}},
    {'service': 'script.einkauf_rezept_einplanen', 'data': {'slug': r.slug, 'name': r.name, 'datum': t.d}}]}}},
  'styles': {
    'card': [{'padding': '10px 14px'}, {'border-radius': '12px'}, {'border': 'none'}, {'box-shadow': 'none'},
